// src/AppCtx.ts
class AppCtx {
  root;
  currView = null;
  constructor(root) {
    this.root = root;
  }
  changeView(view) {
    this.currView?.exit(this);
    this.currView = view;
    this.currView?.enter(this);
  }
  addClickHandler(id, handler) {
    this.root.querySelector(`#${id}`)?.addEventListener("click", handler);
  }
}

// src/game/P2.ts
function coordToLetter(n) {
  return String.fromCharCode(64 + n);
}

class P2 {
  x = 0;
  y = 0;
  constructor(x, y) {
    this.x = x ?? 0;
    this.y = y ?? x ?? 0;
  }
  clone() {
    return new P2(this.x, this.y);
  }
  rounded() {
    return this.clone().round();
  }
  round() {
    this.x = Math.round(this.x);
    this.y = Math.round(this.y);
    return this;
  }
  toString() {
    return `(${this.x}, ${this.y})`;
  }
  name() {
    return `${coordToLetter(this.x)}${this.y}`;
  }
}
function lerp(a, b, t) {
  return a + (b - a) * t;
}

// src/game/Frame.ts
class Frame {
  time;
  deltaTime;
  constructor(time, deltaTime) {
    this.time = time;
    this.deltaTime = deltaTime;
  }
}

