function buildPath(game, tile, start, end) {
  const dir = new float3().subVectors(end, start);
  const len = dir.length();
  const para = dir.clone().divideScalar(len);
  const rng = tile.draw.rng;
  const perp = new float3(-para.y, para.x);
  const animDur = Anims.BaseDur * 0.25;
  game.startCombinedAnim();
  let pathModels = [];
  if (len < 0.1) {
    const size = rng.nextF(0.7, 0.9);
    pathModels.push(game.renderer.growMeshOnTile(game.assets.model_PathStone, tile, Colors3.tileRoad1, animDur, new float3().addScaledVector(para, 0.5 * len).add(start), new float3(size, size, size), Utils3.rotZDeg(rng.nextF(-180, 180))));
  } else {
    const count = Math.ceil(len / 0.3);
    const spacing = len / count;
    for (let i = 1;i < count; ++i) {
      const pos = new float3().addScaledVector(para, i * spacing).addScaledVector(perp, (i % 2 ? -1 : 1) * 0.025).add(start);
      const size = rng.nextF(0.6, 0.75);
      pathModels.push(game.renderer.growMeshOnTile(game.assets.model_PathStone, tile, Colors3.tileRoad1, animDur, pos, new float3(size, size, size), Utils3.rotZDeg(rng.nextF(-180, 180))));
    }
  }
  game.endAndAddCombinedAnim();
  return pathModels;
}

